const button = document.querySelector('#collect'); const status = document.querySelector('#status');
button.addEventListener('click', () => { button.disabled = true; status.textContent = '正在采集…'; chrome.runtime.sendMessage({ type: 'collector:collect', method: 'visible-notes' }, (reply) => { button.disabled = false; if (chrome.runtime.lastError) { status.className = 'error'; status.textContent = chrome.runtime.lastError.message; return; } if (reply?.error) { status.className = 'error'; status.textContent = reply.error; return; } const data = reply.result; status.className = ''; status.textContent = `已入库：新增 ${data.created}，更新 ${data.updated}，重复 ${data.duplicates}。`; }); });
